package com.nori.simple;
import android.Manifest; import android.app.Activity; import android.content.pm.PackageManager; import android.os.Bundle; import android.webkit.*; import androidx.annotation.Nullable; import androidx.webkit.WebViewAssetLoader;
public class MainActivity extends Activity { private WebView webView; private WebViewAssetLoader loader; @Override public void onCreate(@Nullable Bundle s){super.onCreate(s); webView=new WebView(this); setContentView(webView); webView.getSettings().setJavaScriptEnabled(true); webView.getSettings().setDomStorageEnabled(true); webView.getSettings().setMediaPlaybackRequiresUserGesture(false); loader=new WebViewAssetLoader.Builder().addPathHandler("/assets/",new WebViewAssetLoader.AssetsPathHandler(this)).build(); webView.setWebViewClient(new WebViewClient(){@Override public WebResourceResponse shouldInterceptRequest(WebView v,WebResourceRequest r){return loader.shouldInterceptRequest(r.getUrl());}}); webView.setWebChromeClient(new WebChromeClient(){@Override public void onPermissionRequest(final PermissionRequest r){runOnUiThread(()->{if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED)r.grant(r.getResources());else r.deny();});}}); if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},7); webView.loadUrl("https://appassets.androidplatform.net/assets/index.html");} @Override protected void onDestroy(){if(webView!=null)webView.destroy();super.onDestroy();}}
